import { test, expect } from '@playwright/test';

test.describe('Product Image Zoom', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/product');
  });

  test('should allow pinch-to-zoom on product images', async ({ page }) => {
    const productImage = page.getByRole('img', { name: /product image/i });
    await expect(productImage).toBeVisible();

    // Simulate pinch-to-zoom gesture
    await page.mouse.wheel(0, 100); // Zoom in
    await expect(productImage).toHaveCSS('transform', /scale\(1.5\)/);

    await page.mouse.wheel(0, -100); // Zoom out
    await expect(productImage).toHaveCSS('transform', /scale\(1\)/);
  });

  test('should display zoomed image correctly', async ({ page }) => {
    const productImage = page.getByRole('img', { name: /product image/i });
    await expect(productImage).toBeVisible();

    // Simulate pinch-to-zoom gesture
    await page.mouse.wheel(0, 100); // Zoom in
    await expect(productImage).toHaveCSS('transform', /scale\(1.5\)/);

    // Verify that the image is still centered
    const boundingBox = await productImage.boundingBox();
    expect(boundingBox).not.toBeNull();
    expect(boundingBox!.x).toBeLessThanOrEqual(0);
  });
});
